def decrypt(short_arr, offset, length, xor_key):
    """Decrypt using the XOR algorithm: char[i] = short[offset+i] ^ xor_key"""
    result = []
    for i in range(length):
        if offset + i >= len(short_arr):
            break
        val = short_arr[offset + i] ^ xor_key
        # Handle Java short (16-bit signed) - convert to unsigned for char
        if val < 0:
            val = val + 65536
        if val > 0x10FFFF:
            val = val & 0xFFFF  # Truncate to 16-bit
        try:
            result.append(chr(val))
        except:
            result.append('?')
    return ''.join(result)


def is_printable_char(c):
    """Check if a character is printable (ASCII or CJK)"""
    cp = ord(c)
    return (32 <= cp <= 126) or (0x4E00 <= cp <= 0x9FFF) or (0x3000 <= cp <= 0x303F) or \
           (0xFF00 <= cp <= 0xFFEF) or (0x2000 <= cp <= 0x206F) or cp > 0x2E80


def is_meaningful_string(s):
    """Check if a string looks like a meaningful decrypted string"""
    if len(s) < 2:
        return False
    printable_count = sum(1 for c in s if is_printable_char(c))
    return printable_count == len(s)


