def sxor(a, b):
    """Simulate Java int XOR (32-bit signed)"""
    return (a ^ b) & 0xFFFFFFFF

def to_java_int(v):
    """Convert to Java signed int"""
    if v > 0x7FFFFFFF:
        return v - 0x100000000
    return v

