    print(f"    逐字分析:")
    for i, (cp, ch) in enumerate(zip(codepoints, chars)):
        char_name = ""
        if 0x4E00 <= cp <= 0x9FFF:
            char_name = "(CJK统一汉字)"
        elif 32 <= cp <= 126:
            char_name = f"(ASCII: {repr(chr(cp))})"
        elif 0x3000 <= cp <= 0x303F:
            char_name = "(CJK标点)"
        elif cp > 0x9FFF:
            char_name = "(CJK扩展)"
        print(f"      [{offset+i}] {d_short[offset+i]} ^ {xor_key} = {cp} = U+{cp:04X} {ch} {char_name}")

